package com.pocketwise.controller;
import java.util.Map; import org.springframework.web.bind.annotation.*; import org.springframework.security.core.Authentication; import com.pocketwise.model.Budget; import com.pocketwise.repository.BudgetRepository;
@RestController @RequestMapping("/api/budgets") public class BudgetController {private final BudgetRepository repo;public BudgetController(BudgetRepository r){repo=r;} @GetMapping public Budget get(Authentication a){return repo.findById(a.getName()).orElseGet(()->{Budget b=new Budget();b.setId(a.getName());return repo.save(b);});} @PutMapping public Budget update(@RequestBody Budget in,Authentication a){Map<String,Double> c=in.getCategories();if(c==null||c.values().stream().anyMatch(v->v==null||v<0))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Budgets must be non-negative");Budget b=repo.findById(a.getName()).orElseGet(Budget::new);b.setId(a.getName());b.setCategories(c);b.setMonthlyBudget(in.getMonthlyBudget()>0?in.getMonthlyBudget():c.values().stream().mapToDouble(Double::doubleValue).sum());return repo.save(b);}}
